     4	/**
     5	 * The insured items of a policy that have not yet answered for a damage in this incident.
     6	 *
     7	 * The office reads a damage report one entry at a time and strikes off the item that
     8	 * answers for it, so that no item answers twice within one incident.
     9	 */
    10	public class UnclaimedCover {
    11	
    12	    private final List<Item> unclaimed;
    13	
    14	    public UnclaimedCover(List<Item> items) {
    15	        this.unclaimed = new ArrayList<>(items);
    16	    }
    17	
    18	    public Item claimAgainst(Damage damage) {
    19	        for (int position = 0; position < unclaimed.size(); position++) {
    20	            if (unclaimed.get(position).type().equals(damage.itemType())) {
    21	                return unclaimed.remove(position);
    22	            }
