     1	import java.util.List;
     2	
     3	/**
     4	 * What a policy is worth to the office: the insurance sum it has underwritten, and the
     5	 * cap on everything it will ever pay out on that policy.
     6	 *
     7	 * The insurance sum is the plain sum of the listed insurance values of the covered items.
     8	 * It is deliberately taken from the price list rather than from the premium: a block
     9	 * discount lowers what the customer pays without lowering what the office insures, and a
    10	 * risk surcharge raises the premium without raising the cap.
    11	 */
    12	public class PolicyCover {
    13	
    14	    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    15	
    16	    private final int insuranceSum;
    17	
    18	    private PolicyCover(int insuranceSum) {
    19	        this.insuranceSum = insuranceSum;
    20	    }
    21	
    22	    public static PolicyCover of(List<Item> items) {
    23	        PriceList priceList = new PriceList();
    24	        int sum = 0;
    25	        for (Item item : items) {
    26	            sum += priceList.insuranceValueOf(item);
    27	        }
    28	        return new PolicyCover(sum);
    29	    }
    30	
    31	    /**
    32	     * The ceiling the office underwrote: everything it will ever pay out on this policy,
    33	     * twice the insurance sum.
    34	     */
    35	    public int cap() {
    36	        return CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum;
    37	    }
    38	}
=== ClaimOffice ===
     1	import java.util.ArrayList;
     2	import java.util.List;
     3	
     4	/**
     5	 * Works through a scenario's steps in the order the office received them.
     6	 *
     7	 * Each step is handled against the policies already on file: a quote is priced against the
     8	 * history that stands before it and adds the policy it issues to that file, while a claim is
     9	 * settled against a policy the file already holds and so leaves the history untouched.
    10	 */
    11	public class ClaimOffice {
    12	
    13	    private final PremiumCalculator premiumCalculator = new PremiumCalculator();
    14	    private final PayoutCalculator payoutCalculator = new PayoutCalculator();
    15	
    16	    public List<StepResult> run(Scenario scenario) {
    17	        List<StepResult> results = new ArrayList<>();
    18	        PoliciesOnFile policiesOnFile = new PoliciesOnFile();
    19	        for (Step step : scenario.steps()) {
    20	            if (step instanceof QuoteStep quoteStep) {
    21	                results.add(quote(quoteStep, scenario.customer(), policiesOnFile, results.size()));
    22	            } else {
    23	                results.add(settle((ClaimStep) step, policiesOnFile));
    24	            }
    25	        }
    26	        return results;
    27	    }
    28	
    29	    /**
    30	     * Quoting: the premium the office asks for the items, assessed against the contracts that
    31	     * stand before this one, and the policy that premium is quoted for goes on file under the
    32	     * step that quoted it.
    33	     */
    34	    private QuoteResult quote(QuoteStep quoteStep, Customer customer, PoliciesOnFile policiesOnFile,
    35	            int stepIndex) {
    36	        QuoteAssessment assessment =
    37	                new QuoteAssessment(customer, policiesOnFile.contractsOnFile());
    38	        int premium = premiumCalculator.premiumFor(quoteStep, assessment);
    39	        policiesOnFile.issuedBy(stepIndex, new Policy(quoteStep.items()));
    40	        return new QuoteResult(premium);
    41	    }
    42	
    43	    /**
    44	     * Settling a claim against the policy it names: what the office pays for the damages
    45	     * reported, and what that settlement leaves of the cap the policy was underwritten with.
    46	     */
    47	    private ClaimResult settle(ClaimStep claimStep, PoliciesOnFile policiesOnFile) {
    48	        Policy policy = policiesOnFile.namedBy(claimStep);
    49	        int desiredPayout = payoutCalculator.payoutFor(claimStep.incident(), policy.unclaimedCover());
    50	        int payout = policy.settle(desiredPayout);
    51	        return new ClaimResult(payout, policy.remainingCap());
    52	    }
    53	}
=== PayoutCalculator ===
     1	/**
     2	 * What the office pays out for an incident, settled against the cover a policy has left.
     3	 *
     4	 * The office settles an incident one damaged item at a time, and the incident's payout is
     5	 * what those settlements come to. The deductible is withheld per damage event, which is why
     6	 * it belongs to the single settlement and not to the tally.
     7	 *
     8	 * Which item answers for a damage is not this tally's business: the cover is asked, and it
     9	 * either names the item or objects that the policy covers no further item of that type.
    10	 */
    11	public class PayoutCalculator {
    12	
    13	    private static final int DEDUCTIBLE = 100;
    14	
    15	    private final ReimbursementClauses reimbursementClauses = new ReimbursementClauses();
    16	
    17	    public int payoutFor(Incident incident, UnclaimedCover unclaimedCover) {
    18	        double payout = 0;
    19	        for (Damage damage : incident.damages()) {
    20	            payout += settlementFor(damage, unclaimedCover);
    21	        }
    22	        return OfficesFavour.onAmountPaidOut(payout);
    23	    }
    24	
    25	    /**
    26	     * What one damaged item is settled at: the damage the office reimburses under the
    27	     * clauses that cover it, less the deductible it withholds for every damage event.
    28	     */
    29	    private double settlementFor(Damage damage, UnclaimedCover unclaimedCover) {
    30	        return reimbursementClauses.reimbursedAmountFor(damage, unclaimedCover.claimAgainst(damage))
    31	                - DEDUCTIBLE;
    32	    }
    33	}
