=== ReimbursementClauses ===
     1	/**
     2	 * The clauses under which the office reimburses a reported damage, before the deductible.
     3	 *
     4	 * The office reimburses damage in full unless a special clause says otherwise. Damage to a
     5	 * highly enchanted item is reimbursed at half, the magic having borne part of the harm.
     6	 * Each clause fixes the share of a damage the office reimburses on the item that suffered
     7	 * it; full reimbursement is what stands when no special clause speaks.
     8	 *
     9	 * The office states a second clause: damage to an item of dragon material is reimbursed in
    10	 * full. It is deliberately absent here. Full reimbursement is already what stands when no
    11	 * clause speaks, so where the dragon clause alone applies it asks for the amount the office
    12	 * would pay anyway; and where it meets the half clause, the office rules that the half
    13	 * clause wins. No damage the office can be shown is settled differently for knowing the
    14	 * item is of dragon material, so naming it would add a distinction without a difference.
    15	 * That precedence — the half clause prevailing over any clause of full reimbursement — is
    16	 * what the single condition below quietly obeys, and is the rule to restate should a clause
    17	 * ever arrive that does make a difference.
    18	 */
    19	public class ReimbursementClauses {
    20	
    21	    private static final double HALF_REIMBURSEMENT_RATE = 0.50;
    22	
    23	    private static final double FULL_REIMBURSEMENT_RATE = 1.00;
    24	
    25	    /** The enchantment level from which the office reimburses a damage at half. */
    26	    private static final int HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
    27	
    28	    public double reimbursedAmountFor(Damage damage, Item damagedItem) {
    29	        return damage.amount() * reimbursedShareOf(damagedItem);
    30	    }
    31	
    32	    /** The share of a damage the office reimburses on the item that suffered it. */
    33	    private double reimbursedShareOf(Item damagedItem) {
    34	        if (isHighlyEnchanted(damagedItem)) {
    35	            return HALF_REIMBURSEMENT_RATE;
    36	        }
    37	        return FULL_REIMBURSEMENT_RATE;
    38	    }
    39	
    40	    private boolean isHighlyEnchanted(Item item) {
    41	        return item.enchantment() >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
    42	    }
    43	}
=== Policy ===
     1	import java.util.List;
     2	
     3	/**
     4	 * A policy the office has issued: what it covers, and what is left of its cap.
     5	 *
     6	 * The cap is what the office will ever pay out on the policy, so it is consumed as claims
     7	 * are settled: a claim is paid only as far as the cap still reaches, and what it does not
     8	 * reach is not paid at all.
     9	 */
    10	public class Policy {
    11	
    12	    private final List<Item> items;
    13	
    14	    private int remainingCap;
    15	
    16	    public Policy(List<Item> items) {
    17	        this.items = items;
    18	        this.remainingCap = PolicyCover.of(items).cap();
    19	    }
    20	
    21	    /**
    22	     * The cover this policy has left to answer for one incident: every insured item, each
    23	     * able to answer for a single damage before the office objects.
    24	     *
    25	     * A fresh cover is handed out for each incident, because an item that answered for a
    26	     * damage in one incident is insured again for the next.
    27	     */
    28	    public UnclaimedCover unclaimedCover() {
    29	        return new UnclaimedCover(items);
    30	    }
    31	
    32	    public int settle(int desiredPayout) {
    33	        int payout = Math.min(desiredPayout, remainingCap);
    34	        remainingCap -= payout;
    35	        return payout;
    36	    }
    37	
    38	    public int remainingCap() {
    39	        return remainingCap;
    40	    }
    41	}
